    "adds": "yes", "new": ["ledger-sink listens on port 8444."], "same_as_fact": null},
  {"fact_id": "F2", "about": "the conversation", "kind": "momentary", "existing": [], "adds": "no", "new": [], "same_as_fact": null},
  {"fact_id": "F3", "about": "Cleo", "kind": "lasting", "existing": [
